import hre from "hardhat";

async function main() {
    const calldata = "";
    
    console.log(`\n🔍 DECODING CALLDATA`);
    
    const MultiSig = await hre.ethers.getContractFactory("BBSNSMultiSig");
    const decoded = MultiSig.interface.decodeFunctionData("submitTransaction", calldata);
    
    console.log(`- Decoded arguments:`);
    console.log(`  - _to:`, decoded[0]);
    console.log(`  - _value:`, decoded[1]);
    console.log(`  - _data:`, decoded[2]);
    console.log(`  - _proposalHash:`, decoded[3]);
}

main().catch(console.error);
